      "Tarangire otevírá cestu vlastním opravdovým půldnem, k němuž patří zastávka v Mto wa Mbu a návštěva masajské komunity zabudovaná přímo do trasy, nikoli nabízená jako doplněk — domov jedné z největších sloních populací ve východní Africe, soustředěné v období sucha podél řeky. Kráter Ngorongoro dostává celý den místo uspěchané dopolední zastávky: zhroucená sopečná kaldera o rozloze zhruba 260 km², jejíž stěny jsou tak strmé, že většina toho, co uvnitř žije, ji nikdy neopustí, a jeden z nejkoncentrovanějších dnů pozorování divoké zvěře na celém okruhu. Následují dva celé dny v území domácích predátorů Serengeti, než vyhlídkový let — vedený přes Arushu — vymění vozidlo za otevřenou vodu a tři nenaplánované noci na bílém písku Nungwi.",
